105	function createCommitMessage(changes: Map<string, PendingChange>) {
106	    const messages = [...changes.values()].flatMap(({ messages: entryMessages }) => entryMessages)
107	    const distinctMessages = [...new Set(messages)]
108	    if (distinctMessages.length === 1) return distinctMessages[0]
109	
110	    const body = distinctMessages.map((message) => `- ${message}`).join('\n')
111	
112	    return `Update ${changes.size} files\n\n${body}`
