18	export async function runElectronAction(
19	    action: ActionDefinition,
20	    context: ActionContext,
21	    input: ActionRunInput = {},
22	    onStarted?: (runId: string) => void,
23	    interactive = true,
24	): Promise<ActionRunResult> {
25	    try {
26	        projectAccessService.requireWritable();
27	        const requiresReservation = shouldReserveConversation(action, context, input)
28	        const bridge = getElectronActionBridge()
29	        const conversationReservation: AgentConversationReservation | undefined = requiresReservation
30	            ? await bridge?.reserveActionConversation?.({ actionId: action.id, context, runInput: input })
31	            : undefined
32	        if (requiresReservation && !conversationReservation) {
33	            throw new Error('Starting a card agent requires conversation reservation support')
34	        }
35	        if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()
36	        return await actionRunRegistry.startRun(action, context, input, onStarted, interactive, conversationReservation)
37	    } catch (error) {
38	        if (input.submissionId) actionRunRegistry.failSubmission(input.submissionId, error instanceof Error ? error.message : 'Action run failed');
39	        throw error;
40	    }
41	}
